		Sender: sender,
		CodeID: codeID,
		Label:  label,
		Msg:    msgArgs,
		Funds:  funds,
	}
	if len(admin) > 0 {
		txMsg.Admin = admin
	}
	return txMsg, txMsg.ValidateBasic()
}
```

However, in the `ValidateBasic` function, only the `AccAddressFromBech32` function is used to check the format, and the legitimacy of the `admin` address is not verified.

```go
